package com.clothingstore;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="order_items") public class OrderItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="order_id") private StoreOrder order; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="product_id") private Product product; @Column(name="product_name") private String productName; @Column(name="unit_price") private BigDecimal unitPrice; private Integer quantity; @Column(name="line_total") private BigDecimal lineTotal; public void setOrder(StoreOrder v){order=v;} public void setProduct(Product v){product=v;} public void setProductName(String v){productName=v;} public void setUnitPrice(BigDecimal v){unitPrice=v;} public void setQuantity(Integer v){quantity=v;} public void setLineTotal(BigDecimal v){lineTotal=v;} public BigDecimal getLineTotal(){return lineTotal;} }
